  name        = "${var.environment}-${var.tenant_id}-sg"
  description = "Tenant-specific security group"

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lambda_function" "tenant_processor" {
  function_name = "${var.environment}-${var.tenant_id}-processor"
  role          = aws_iam_role.lambda_role.arn
  handler       = "lambda.handler"
  runtime       = "python3.9"

  code {
    s3_bucket     = var.code_bucket
    s3_key        = "${var.environment}/${var.tenant_id}/function.zip"
  }

  environment {
    variables = {
      TENANT_ID   = var.tenant_id
      ENVIRONMENT = var.environment
      LOG_LEVEL   = "INFO"
    }
  }
}
```

